<?php include 'verifica_login.php'; include 'conexao.php'; include '_layout.php';$id=id_get('id');
if($_SERVER['REQUEST_METHOD']==='POST'){ $idi=(int)($_POST['id_inscricao']??0);$nota=esc($conexao,$_POST['nota']??'');$class=esc($conexao,$_POST['classificacao']??'');if(!$idi)erro('Selecione a inscrição.');$ok=mysqli_query($conexao,"UPDATE resultados SET id_inscricao=$idi, nota='$nota', classificacao='$class' WHERE id_resultado=$id");if(!$ok)erro(mysqli_error($conexao));redirect('lista_resultados.php');}
$r=mysqli_query($conexao,"SELECT * FROM resultados WHERE id_resultado=$id");if(!$r||mysqli_num_rows($r)!==1)erro('Resultado não encontrado.');$row=mysqli_fetch_assoc($r);$ins=mysqli_query($conexao,"SELECT i.id_inscricao,i.nome,c.nome AS concurso FROM inscricoes i INNER JOIN concursos c ON c.id_concurso=i.id_concurso ORDER BY i.nome");
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Editar Resultado</title><?php include 'includes_painel/head.php'; ?><?php include '_form_style.php'; ?></head><body><?php include 'includes_painel/header.php'; ?><div class="crud"><div class="card"><h1>Editar Resultado</h1><form method="post"><div class="grid"><div class="campo full"><label>Candidato / Inscrição</label><select name="id_inscricao" required><?php while($i=mysqli_fetch_assoc($ins)):?><option value="<?=$i['id_inscricao']?>" <?=($row['id_inscricao']??0)==$i['id_inscricao']?'selected':''?>><?=h($i['nome'].' — '.$i['concurso'])?></option><?php endwhile;?></select></div><div class="campo"><label>Nota</label><input type="number" step="0.01" name="nota" value="<?=h($row['nota']??'')?>"></div><div class="campo"><label>Classificação</label><input name="classificacao" value="<?=h($row['classificacao']??'')?>"></div></div><div class="acoes"><button class="btn salvar">Salvar alterações</button><a class="btn voltar" href="lista_resultados.php">Cancelar</a></div></form></div></div></body></html>
